[
  {
    "statement": "No studies have been found that evaluated the combined effects on peatland vegetation of changing both the type of livestock and the season of grazing.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects on peatland vegetation of changing the season or timing of livestock grazing.",
    "citations": [
      "1737"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on peatland vegetation of changing livestock type.",
    "citations": [
      "1736"
    ]
  },
  {
    "statement": "Reducing grazing intensity increased total vegetation and shrub cover in bogs.",
    "citations": [
      "1735"
    ]
  },
  {
    "statement": "Excluding livestock entirely from degraded peatlands has various effects.",
    "citations": [
      "1734"
    ]
  },
  {
    "statement": "There is no research examining the specific combined effects of simultaneously changing both livestock type and grazing season.",
    "citations": []
  }
]

[
  {
    "statement": "No evidence was found regarding the impact of reintroducing beavers on the vegetation of Patagonian peatlands.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effects of introducing beavers in forest environments.",
    "citations": [
      "1187"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on marsh/swamp vegetation of reintroducing overharvested animals.",
    "citations": [
      "3018"
    ]
  },
  {
    "statement": "No action documents were identified that specifically address beaver reintroduction in Patagonian peatlands.",
    "citations": []
  },
  {
    "statement": "No action documents were identified that specifically address the vegetation impacts of beavers in the Patagonian peatland ecosystem.",
    "citations": []
  }
]

[
  {
    "statement": "Specific studies examining the long-term effects (over 30 years) of prescribed fire on bog vegetation composition are limited.",
    "citations": []
  },
  {
    "statement": "The available research on the effects of prescribed fire on bog vegetation includes studies with shorter time periods.",
    "citations": []
  },
  {
    "statement": "Six studies evaluated the effects on peatland vegetation of using prescribed fire to control problematic plants.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "Of the six studies on peatland vegetation, five were conducted in bogs and one was conducted in fens.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "One replicated, paired, controlled study in bogs in Germany found that burning increased moss, lichen, and bare ground cover in the short term (2-7 months after burning).",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "Three replicated, paired studies in one bog in the UK found that moss cover, including Sphagnum, was higher in plots that were burned more often.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "One replicated, paired, controlled study in bogs in the UK found that burning increased cottongrass cover after 8-18 years.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "Two replicated, paired studies in a bog in the UK reported that cottongrass cover was similar in plots burned every 10 years and plots burned every 20 years.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "A study in Germany found that burning reduced purple moor grass cover.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "A study in Germany found that burning had mixed effects among sites on the cover of other grass-like plants and forbs.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "Three replicated, paired studies in a bog in the UK found that heather cover was lower in plots that were burned more often.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "One replicated, paired, controlled study in bogs in Germany found that heather cover was lower in burned plots than in unburned plots.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "A replicated, paired, controlled study in a bog in the UK found that plots burned more frequently contained more biomass of grass-like plants than plots burned less often.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "A replicated, paired, controlled study in a bog in the UK found that plots burned more frequently contained less total vegetation, shrub, and bryophyte biomass.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "Two replicated, controlled studies in fens in the USA and a bog in the UK found that burning reduced or limited plant species richness.",
    "citations": [
      "1774"
    ]
  },
  {
    "statement": "None of the identified studies specifically examined effects of prescribed fire on bog vegetation composition over a 30-year period or longer.",
    "citations": []
  }
]
